// Retina-crisp canvas: enlarge the backing store by devicePixelRatio (capped 2x,
// matching pretext.html) and scale the context so all drawing keeps using the
// canvas's logical width/height. Returns the logical {w,h} to read in draw code
// (reading cv.width after this returns the scaled size). Without it the fixed-size
// bitmap is upscaled by CSS and reads soft on Retina. Call once per canvas.
function hd(cv, cx){ var d = Math.min(window.devicePixelRatio || 1, 2), w = cv.width, h = cv.height; cv.width = w * d; cv.height = h * d; cx.setTransform(d, 0, 0, d, 0, 0); return { w: w, h: h }; }
// ── shared live audio for the demos ──────────────────────────────────
// One AudioContext, one voice at a time (starting a demo stops the others), so
// you hit play once and then HEAR the knobs move: turning a slider or flipping a
// toggle retunes the running graph in real time instead of firing a new one-shot
// (the old autopause meant re-clicking to hear a change). Memoryless transfer
// curves — the quantizer staircase, the tube curve, the R-2R ladder — ride a
// WaveShaperNode whose .curve we swap live (oversampled 4x to tame aliasing);
// the delta-sigma feedback loop and the reconstruction filter need their own
// small graphs. Audio only ever starts on a click, so autoplay policy and
// prefers-reduced-motion need nothing special here.
var DACAudio = (function(){
  var ac = null, current = null;                                     // current = the running demo's stop fn
  function ctx(){ try { ac = ac || new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return null; } if (ac.resume) ac.resume(); return ac; }
  // sample a transfer function fn(x), x in [-1,1], into a WaveShaper curve,
  // DC-removed + peak-normalized so loudness stays put as you turn the knob
  function curve(fn, n){
    n = n || 2048; var a = new Float32Array(n), i, mean = 0, peak = 1e-6;
    for (i = 0; i < n; i++){ a[i] = fn(i / (n - 1) * 2 - 1); mean += a[i]; }
    mean /= n;
    for (i = 0; i < n; i++){ a[i] -= mean; var m = Math.abs(a[i]); if (m > peak) peak = m; }
    for (i = 0; i < n; i++) a[i] /= peak;
    return a;
  }
  function attack(g, c, level){ var t = c.currentTime; g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(level, t + 0.03); }
  function release(g, c){ var t = c.currentTime; g.gain.cancelScheduledValues(t); g.gain.setValueAtTime(Math.max(g.gain.value, 0.0001), t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.05); return t + 0.07; }
  // a sine → WaveShaper(curveFn) → gain voice; retune() re-bakes the curve live
  function shaperVoice(c, freq, curveFn, level){
    var osc = c.createOscillator(); osc.type = 'sine'; osc.frequency.value = freq;
    var ws = c.createWaveShaper(); ws.oversample = '4x'; ws.curve = curveFn();
    var g = c.createGain(); attack(g, c, level || 0.2);
    osc.connect(ws); ws.connect(g); g.connect(c.destination); osc.start();
    return { stop: function(){ osc.stop(release(g, c)); }, retune: function(){ ws.curve = curveFn(); } };
  }
  // wire a play/stop button to a builder(ctx) -> {stop, retune}. returns a handle
  // whose .retune() the demo calls on any knob change (a no-op when not playing)
  function wire(btn, build){
    var voice = null;
    function stopMe(){ if (voice){ try { voice.stop(); } catch (e) {} voice = null; } btn.textContent = 'play'; btn.setAttribute('aria-pressed', 'false'); }
    btn.addEventListener('click', function(){
      if (voice){ stopMe(); current = null; return; }                // stop me
      var c = ctx(); if (!c) return;
      if (current) current();                                        // stop whoever else is playing
      voice = build(c); btn.textContent = 'stop'; btn.setAttribute('aria-pressed', 'true'); current = stopMe;
    });
    return { retune: function(){ if (voice && voice.retune) voice.retune(); }, attack: attack, release: release };
  }
  return { ctx: ctx, curve: curve, shaperVoice: shaperVoice, wire: wire, attack: attack, release: release };
})();

// ── Demo A: multibit staircase ───────────────────────────────────────
(function(){
  var c=document.getElementById('stairCanvas'); if(!c) return;
  var ctx=c.getContext('2d'), bits=document.getElementById('stairBits'), lbl=document.getElementById('stairN');
  var W=c.width, H=c.height, mid=H/2, amp=H*0.40, cycles=2, samples=48; hd(c, ctx);
  function draw(){
    var N=+bits.value, L=Math.pow(2,N), maxv=L/2-1;
    lbl.textContent=N+'-bit · '+L.toLocaleString()+' levels';
    ctx.clearRect(0,0,W,H);
    if(N<=5){ ctx.strokeStyle='#efe6d8'; ctx.lineWidth=1; for(var k=-maxv;k<=maxv;k++){ var yy=mid-(k/maxv)*amp; ctx.beginPath(); ctx.moveTo(0,yy); ctx.lineTo(W,yy); ctx.stroke(); } }
    ctx.strokeStyle='#cbb89e'; ctx.lineWidth=1.5; ctx.beginPath();
    for(var x=0;x<=W;x++){ var t=x/W*cycles*2*Math.PI, y=mid-Math.sin(t)*amp; x?ctx.lineTo(x,y):ctx.moveTo(x,y); }
    ctx.stroke();
    ctx.strokeStyle='#a8541f'; ctx.lineWidth=2; ctx.beginPath();
    for(var i=0;i<samples;i++){ var s=Math.sin(i/samples*cycles*2*Math.PI), q=Math.round(s*maxv)/maxv, x0=i/samples*W, x1=(i+1)/samples*W, yq=mid-q*amp; i?ctx.lineTo(x0,yq):ctx.moveTo(x0,yq); ctx.lineTo(x1,yq); }
    ctx.stroke();
  }
  var voice=DACAudio.wire(document.getElementById('stairPlay'), function(ac){
    return DACAudio.shaperVoice(ac, 220, function(){ var Nb=+bits.value, m=Math.pow(2,Nb)/2-1; return DACAudio.curve(function(x){ return Math.round(x*m)/m; }); }, 0.2);
  });
  bits.addEventListener('input',function(){ draw(); voice.retune(); }); draw();
})();

// ── Demo B: delta-sigma noise shaping (real DFT) ──────────────────────
(function(){
  var c=document.getElementById('nsCanvas'); if(!c) return;
  var ctx=c.getContext('2d'), btn=document.getElementById('nsToggle'), info=document.getElementById('nsInfo');
  var W=c.width, H=c.height, N=512, shape=true, BITS=3; hd(c, ctx);
  function clamp(v){ return v>1?1:(v<-1?-1:v); }
  function spectrum(){
    var maxv=Math.pow(2,BITS)/2-1, k0=6, y=new Array(N), e=0;
    for(var n=0;n<N;n++){
      var s=0.7*Math.sin(2*Math.PI*k0*n/N), q;
      if(shape){ var w=s-e; q=clamp(Math.round(w*maxv)/maxv); e=q-w; }
      else { q=clamp(Math.round(s*maxv)/maxv); }
      y[n]=q;
    }
    var half=N/2, mag=new Array(half);
    for(var k=0;k<half;k++){ var re=0,im=0; for(var m=0;m<N;m++){ var a=2*Math.PI*k*m/N; re+=y[m]*Math.cos(a); im-=y[m]*Math.sin(a); } mag[k]=Math.sqrt(re*re+im*im)/N; }
    return mag;
  }
  function draw(){
    info.textContent=BITS+'-bit quantizer, '+(shape?'1st-order shaping':'no shaping');
    btn.textContent='noise shaping: '+(shape?'ON':'OFF');
    var mag=spectrum(), half=mag.length, band=Math.floor(half*0.25);
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#f3ece1'; ctx.fillRect(0,0,band/half*W,H);
    var top=0, bot=-120;
    function py(db){ return H-((db-bot)/(top-bot))*H; }
    ctx.strokeStyle=shape?'#a8541f':'#8a93a0'; ctx.lineWidth=1.5; ctx.beginPath();
    for(var k=0;k<half;k++){ var x=k/half*W, db=20*Math.log10(mag[k]+1e-9), yy=py(db); k?ctx.lineTo(x,yy):ctx.moveTo(x,yy); }
    ctx.stroke();
  }
  function nsBuf(ac){                                                  // ~1.2s loop of the 3-bit tone, integer cycles so the tone seam is clean
    var sr=ac.sampleRate, len=Math.floor(sr*1.2), k=Math.round(300*len/sr), f=k*sr/len;
    var buf=ac.createBuffer(1,len,sr), ch=buf.getChannelData(0), maxv=Math.pow(2,BITS)/2-1, e=0;
    for(var i=0;i<len;i++){ var s=0.6*Math.sin(2*Math.PI*f*i/sr), q; if(shape){ var w=s-e; q=clamp(Math.round(w*maxv)/maxv); e=q-w; } else { q=clamp(Math.round(s*maxv)/maxv); } ch[i]=q; }
    return buf;
  }
  var nsVoice=DACAudio.wire(document.getElementById('nsPlay'), function(ac){
    var g=ac.createGain(); DACAudio.attack(g,ac,0.26); g.connect(ac.destination); var src=null;
    function run(){ src=ac.createBufferSource(); src.loop=true; src.buffer=nsBuf(ac); src.connect(g); src.start(); }
    run();
    return { stop:function(){ var end=DACAudio.release(g,ac); if(src){ try{src.stop(end);}catch(e){} } }, retune:function(){ if(src){ try{src.stop();}catch(e){} src.disconnect(); } run(); } };
  });
  btn.addEventListener('click',function(){ shape=!shape; draw(); nsVoice.retune(); }); draw();
})();

// ── Demo C: hear the bit depth (Web Audio, user gesture) ──────────────
(function(){
  var wrap=document.getElementById('hearBtns'); if(!wrap) return; var actx=null;
  wrap.addEventListener('click',function(ev){
    var b=ev.target.closest&&ev.target.closest('button[data-bits]'); if(!b) return;
    var bits=+b.getAttribute('data-bits');
    try{ actx=actx||new (window.AudioContext||window.webkitAudioContext)(); }catch(e){ return; }
    if(actx.resume) actx.resume();
    var sr=actx.sampleRate, len=Math.floor(sr*1.1), buf=actx.createBuffer(1,len,sr), ch=buf.getChannelData(0);
    var maxv=Math.pow(2,bits)/2-1, f=440;
    for(var i=0;i<len;i++){
      var env=Math.min(1, i/(sr*0.02), (len-i)/(sr*0.06)), s=Math.sin(2*Math.PI*f*i/sr)*0.25;
      ch[i]=(maxv>0?Math.round(s*maxv)/maxv:0)*env;
    }
    var src=actx.createBufferSource(); src.buffer=buf; src.connect(actx.destination); src.start();
  });
})();
// ── Demo: the R-2R ladder (binary weighting + why precision matters) ──
// An N-bit voltage-mode R-2R ladder. Each bit i contributes Vref * 2^i / 2^N,
// so the MSB is half of Vref, the next a quarter, and so on, built from just
// two resistor values. A tolerance on those resistors perturbs each bit's
// weight; errors in the big bits bend the transfer curve and can break
// monotonicity (a higher code yields a lower voltage), the failure a real
// ladder must engineer away. Per-bit error directions are fixed so the slider
// only scales them.
(function(){
  var wrap = document.getElementById('ladderBits'); if (!wrap) return;
  var out = document.getElementById('ladderOut'), tol = document.getElementById('ladderTol'), tolL = document.getElementById('ladderTolL');
  var xfer = document.getElementById('ladderXfer'), xctx = xfer && xfer.getContext('2d');
  var xdim = xctx ? hd(xfer, xctx) : { w: 0, h: 0 };
  var N = 6, MAX = (1 << N) - 1, code = 1 << (N - 1);
  var dir = [0.7, -0.9, 0.4, -0.6, 0.85, -0.3]; // fixed error direction per bit (index = bit i, LSB..MSB)
  var html = '';
  for (var b = N - 1; b >= 0; b--) html += '<button class="dac-bit" type="button" data-b="' + b + '" aria-pressed="false">b' + b + '<span>Vref/' + Math.pow(2, N - b) + '</span></button>';
  wrap.innerHTML = html;
  function weights(t) { var w = []; for (var i = 0; i < N; i++) w[i] = (Math.pow(2, i) / Math.pow(2, N)) * (1 + dir[i] * t); return w; }
  function vout(c, w) { var v = 0; for (var i = 0; i < N; i++) if (c & (1 << i)) v += w[i]; return v; }
  function render() {
    var t = (+tol.value) / 100; if (tolL) tolL.textContent = (+tol.value).toFixed(1) + '%';
    var w = weights(t);
    if (out) out.textContent = 'Vout = ' + vout(code, w).toFixed(3) + ' Vref   (code ' + code + ' of ' + MAX + ')';
    var btns = wrap.querySelectorAll('.dac-bit');
    for (var k = 0; k < btns.length; k++) { var bb = +btns[k].getAttribute('data-b'); btns[k].setAttribute('aria-pressed', (code & (1 << bb)) ? 'true' : 'false'); }
    if (!xctx) return;
    var W = xdim.w, H = xdim.h; xctx.clearRect(0, 0, W, H);
    xctx.strokeStyle = '#cbb89e'; xctx.lineWidth = 1.2; xctx.beginPath();
    for (var c = 0; c <= MAX; c++) { var x = 5 + c / MAX * (W - 10), y = H - 5 - (c / MAX) * (H - 10); c ? xctx.lineTo(x, y) : xctx.moveTo(x, y); }
    xctx.stroke();
    var vfull = vout(MAX, w) || 1, px = null, pv = 0;
    for (var c2 = 0; c2 <= MAX; c2++) {
      var v = vout(c2, w), X = 5 + c2 / MAX * (W - 10), Y = H - 5 - (v / vfull) * (H - 10);
      if (px) { var nm = v < pv - 1e-9; xctx.strokeStyle = nm ? '#c0392b' : '#a8541f'; xctx.lineWidth = nm ? 2.4 : 1.6; xctx.beginPath(); xctx.moveTo(px.x, px.y); xctx.lineTo(X, Y); xctx.stroke(); }
      px = { x: X, y: Y }; pv = v;
    }
  }
  var lVoice = DACAudio.wire(document.getElementById('ladderPlay'), function(ac){
    return DACAudio.shaperVoice(ac, 180, function(){                          // map a full-scale sine through the code→voltage transfer curve
      var w = weights((+tol.value) / 100), vfull = vout(MAX, w) || 1;
      return DACAudio.curve(function(x){ var cd = Math.round((x + 1) / 2 * MAX); if (cd < 0) cd = 0; if (cd > MAX) cd = MAX; return vout(cd, w) / vfull * 2 - 1; });
    }, 0.2);
  });
  wrap.addEventListener('click', function(e) { var b = e.target.closest && e.target.closest('.dac-bit'); if (!b) return; code ^= (1 << +b.getAttribute('data-b')); render(); });
  if (tol) tol.addEventListener('input', function(){ render(); lVoice.retune(); });
  render();
})();

// ── Demo: the reconstruction filter, a time vs frequency tradeoff ─────
// A windowed-sinc reconstruction filter. Raising the tap count sharpens the
// frequency roll-off near Nyquist but lengthens the impulse response, so the
// ringing in time grows. You cannot be arbitrarily sharp in both domains: that
// is the Fourier uncertainty tradeoff that NOS, oversampling, apodizing, and
// closed-form filters each answer differently.
(function(){
  var sh = document.getElementById('filtSharp'); if (!sh) return;
  var shL = document.getElementById('filtSharpL');
  var tC = document.getElementById('filtTime'), fC = document.getElementById('filtFreq');
  var tctx = tC && tC.getContext('2d'), fctx = fC && fC.getContext('2d');
  var td = tctx ? hd(tC, tctx) : { w: 0, h: 0 }, fd = fctx ? hd(fC, fctx) : { w: 0, h: 0 };
  function sinc(x) { return x === 0 ? 1 : Math.sin(Math.PI * x) / (Math.PI * x); }
  function build(s) {
    var L = Math.round(7 + s * 7) * 2 + 1, c = (L - 1) / 2, fc = 0.45, h = [];
    for (var n = 0; n < L; n++) {
      var win = 0.5 - 0.5 * Math.cos(2 * Math.PI * n / (L - 1)); // Hann
      h.push(sinc(2 * fc * (n - c)) * win);
    }
    return h;
  }
  function dft(h, M) {
    var mag = [];
    for (var k = 0; k < M; k++) {
      var re = 0, im = 0, f = 0.5 * k / (M - 1); // 0..Nyquist
      for (var n = 0; n < h.length; n++) { var a = 2 * Math.PI * f * n; re += h[n] * Math.cos(a); im -= h[n] * Math.sin(a); }
      mag.push(Math.sqrt(re * re + im * im));
    }
    var peak = Math.max.apply(null, mag) || 1;
    return mag.map(function(m) { return m / peak; });
  }
  function draw() {
    var s = +sh.value; if (shL) shL.textContent = (s < 3 ? 'gentle' : s < 6 ? 'medium' : 'sharp') + ' (' + (Math.round(7 + s * 7) * 2 + 1) + ' taps)';
    var h = build(s);
    if (tctx) {
      var W = td.w, H = td.h, mid = H / 2; tctx.clearRect(0, 0, W, H);
      tctx.strokeStyle = '#efe6d8'; tctx.beginPath(); tctx.moveTo(0, mid); tctx.lineTo(W, mid); tctx.stroke();
      tctx.strokeStyle = '#a8541f'; tctx.lineWidth = 1.6; tctx.beginPath();
      for (var n = 0; n < h.length; n++) { var x = n / (h.length - 1) * W, y = mid - h[n] * (H * 0.40); n ? tctx.lineTo(x, y) : tctx.moveTo(x, y); }
      tctx.stroke();
    }
    if (fctx) {
      var W2 = fd.w, H2 = fd.h, mag = dft(h, 160); fctx.clearRect(0, 0, W2, H2);
      fctx.fillStyle = '#f3ece1'; fctx.fillRect(0, 0, 0.9 * W2, H2); // passband shade to ~0.45 Nyquist
      fctx.strokeStyle = '#a8541f'; fctx.lineWidth = 1.6; fctx.beginPath();
      for (var k = 0; k < mag.length; k++) { var db = 20 * Math.log10(mag[k] + 1e-6), x2 = k / (mag.length - 1) * W2, y2 = H2 - ((db + 80) / 80) * H2; k ? fctx.lineTo(x2, y2) : fctx.moveTo(x2, y2); }
      fctx.stroke();
    }
  }
  function irBuf(ac){ var h=build(+sh.value), len=h.length, b=ac.createBuffer(1,len,ac.sampleRate), d=b.getChannelData(0), pk=1e-6; for(var i=0;i<len;i++){ var m=Math.abs(h[i]); if(m>pk)pk=m; } for(i=0;i<len;i++) d[i]=h[i]/pk; return b; }
  var fVoice=DACAudio.wire(document.getElementById('filtPlay'), function(ac){
    var conv=ac.createConvolver(); conv.normalize=false; conv.buffer=irBuf(ac);
    var g=ac.createGain(); DACAudio.attack(g,ac,0.4);
    var sr=ac.sampleRate, per=Math.floor(sr*0.5), len=per*3, cb=ac.createBuffer(1,len,sr), cd=cb.getChannelData(0);  // a click every 0.5s, looped; convolved with the kernel = the impulse response you can hear
    for(var kk=0;kk<3;kk++) cd[kk*per]=1;
    var src=ac.createBufferSource(); src.buffer=cb; src.loop=true; src.connect(conv); conv.connect(g); g.connect(ac.destination); src.start();
    return { stop:function(){ var end=DACAudio.release(g,ac); try{src.stop(end);}catch(e){} }, retune:function(){ conv.buffer=irBuf(ac); } };
  });
  sh.addEventListener('input', function(){ draw(); fVoice.retune(); }); draw();
})();

// ── Demo: the contested ground — low-level linearity, multibit vs delta-sigma ──
// Where the "musicality" argument actually lives: a QUIET tone (the soft tail of a
// note), where only the lowest bits are working. Multibit rounds to its nearest
// exact level, which at low level bends the wave into harmonic DISTORTION. Delta-
// sigma keeps the average level honest but rides a shaped NOISE floor. Same tone,
// two flavors of imperfection, shown as spectra and playable. Crank the bits toward
// 16 and both fall below hearing: the honest reason the debate never settles.
(function(){
  var bits = document.getElementById('muBits'); if (!bits) return;
  var bitsL = document.getElementById('muBitsL');
  var mbC = document.getElementById('muMbCanvas'), dsC = document.getElementById('muDsCanvas');
  var mbCtx = mbC && mbC.getContext('2d'), dsCtx = dsC && dsC.getContext('2d');
  var mbd = mbCtx ? hd(mbC, mbCtx) : { w: 0, h: 0 }, dsd = dsCtx ? hd(dsC, dsCtx) : { w: 0, h: 0 };
  var mbInfo = document.getElementById('muMbInfo'), dsInfo = document.getElementById('muDsInfo');
  var N = 512, K0 = 5, AMP = 0.08, actx = null; // a quiet tone at bin K0
  function clamp(v){ return v > 1 ? 1 : v < -1 ? -1 : v; }
  function quantize(B, shape){
    var maxv = Math.pow(2, B - 1) - 1, y = new Array(N), e = 0;
    for (var n = 0; n < N; n++){
      var x = AMP * Math.sin(2 * Math.PI * K0 * n / N), q;
      if (shape){ var w = x - e; q = clamp(Math.round(w * maxv) / maxv); e = q - w; }
      else { q = clamp(Math.round(x * maxv) / maxv); }
      y[n] = q;
    }
    return y;
  }
  function spectrum(y){
    var half = N / 2, mag = new Array(half);
    for (var k = 0; k < half; k++){ var re = 0, im = 0; for (var n = 0; n < N; n++){ var a = 2 * Math.PI * k * n / N; re += y[n] * Math.cos(a); im -= y[n] * Math.sin(a); } mag[k] = Math.sqrt(re * re + im * im) / N; }
    return mag;
  }
  function drawSpec(ctx, mag, accent, dim){
    var W = dim.w, H = dim.h, half = mag.length;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#f3ece1'; ctx.fillRect((K0 - 1) / half * W, 0, 3 / half * W, H); // tone band
    function py(db){ return H - ((db + 120) / 120) * H; }
    ctx.strokeStyle = accent; ctx.lineWidth = 1.4; ctx.beginPath();
    for (var k = 0; k < half; k++){ var x = k / half * W, db = 20 * Math.log10(mag[k] + 1e-9), y = py(db); k ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
    ctx.stroke();
  }
  function render(){
    var B = +bits.value; if (bitsL) bitsL.textContent = B + '-bit';
    var sm = spectrum(quantize(B, false)), sd = spectrum(quantize(B, true));
    if (mbCtx) drawSpec(mbCtx, sm, '#a8541f', mbd);
    if (dsCtx) drawSpec(dsCtx, sd, '#2f6fd0', dsd);
    var harm = 0; for (var h = 2; h * K0 < N / 2; h++) harm += sm[h * K0] * sm[h * K0];      // multibit distortion
    var noise = 0; for (var k = 1; k < N / 2; k++){ if (Math.abs(k - K0) <= 1) continue; noise += sd[k] * sd[k]; } // ds noise
    if (mbInfo) mbInfo.textContent = harm > 2e-6 ? 'harmonic distortion' : 'clean';
    if (dsInfo) dsInfo.textContent = noise > 2e-6 ? 'shaped noise floor' : 'clean';
  }
  function play(shape){
    try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return; }
    if (actx.resume) actx.resume();
    var B = +bits.value, sr = actx.sampleRate, len = Math.floor(sr * 1.3), buf = actx.createBuffer(1, len, sr), ch = buf.getChannelData(0);
    var maxv = Math.pow(2, B - 1) - 1, f = 440, e = 0;
    for (var i = 0; i < len; i++){
      var env = Math.min(1, i / (sr * 0.02), (len - i) / (sr * 0.06)), x = AMP * Math.sin(2 * Math.PI * f * i / sr), q;
      if (shape){ var w = x - e; q = clamp(Math.round(w * maxv) / maxv); e = q - w; }
      else { q = clamp(Math.round(x * maxv) / maxv); }
      ch[i] = q * env * 2.2; // gain the quiet tone up so the imperfection is audible (kept gentle)
    }
    var s = actx.createBufferSource(); s.buffer = buf; s.connect(actx.destination); s.start();
  }
  bits.addEventListener('input', render);
  var grid = document.querySelector('.mu-grid');
  if (grid) grid.addEventListener('click', function(ev){ var b = ev.target.closest && ev.target.closest('[data-topo]'); if (b) play(b.getAttribute('data-topo') === 'ds'); });
  render();
})();

// ── Demo: tube distortion — the "warmth" axis, even vs odd harmonics ──
// After the DAC the analog signal meets an amplifier, and this is where the word
// "warmth" is actually earned. A single tube's transfer curve is gently
// asymmetric, so a driven sine grows mostly the 2nd harmonic — one octave up,
// which the ear reads as consonant/full. A hard SYMMETRIC clip cancels the even
// harmonics and grows odd ones (3rd, 5th, 7th...), marching toward a square wave:
// the buzz of a signal slammed into its rails. Two deliberately clean, contrasting
// curves: tube = x + c*x^2 (dominant 2nd, even), clip = clamp(g*x) (odd, → square).
// The spectrum bars read a DFT sampled over an integer number of cycles (K0 cycles
// / N samples), so every harmonic lands exactly on a bin. Renders on interaction
// only — no animation loop, so prefers-reduced-motion needs nothing special.
(function(){
  var driveEl = document.getElementById('tubeDrive'); if (!driveEl) return;
  var driveL = document.getElementById('tubeDriveL'), info = document.getElementById('tubeInfo');
  var xferC = document.getElementById('tubeXfer'), waveC = document.getElementById('tubeWave'), specC = document.getElementById('tubeSpec');
  var xc = xferC && xferC.getContext('2d'), wc = waveC && waveC.getContext('2d'), sc = specC && specC.getContext('2d');
  var xd = xc ? hd(xferC, xc) : { w: 0, h: 0 }, wd = wc ? hd(waveC, wc) : { w: 0, h: 0 }, sd = sc ? hd(specC, sc) : { w: 0, h: 0 };
  var modeBtns = document.querySelectorAll('.tmode'), playBtn = document.getElementById('tubePlay');
  var mode = 'tube', A = 0.9, N = 600, K0 = 6;
  function clampv(v){ return v > 1 ? 1 : v < -1 ? -1 : v; }
  function shape(x, drive){
    if (mode === 'clip') { var g = 1 + drive * 0.9; return clampv(g * x); }   // symmetric hard clip → odd / square
    var c = drive * 0.11; return x + c * x * x;                               // asymmetric soft curve → 2nd harmonic
  }
  function series(drive){                                                     // one window, DC-removed + peak-normalized
    var y = new Array(N), mean = 0, peak = 1e-9, n;
    for (n = 0; n < N; n++){ y[n] = shape(A * Math.sin(2 * Math.PI * K0 * n / N), drive); mean += y[n]; }
    mean /= N;
    for (n = 0; n < N; n++){ y[n] -= mean; var a = Math.abs(y[n]); if (a > peak) peak = a; }
    for (n = 0; n < N; n++) y[n] /= peak;
    return y;
  }
  function harmonics(y, H){                                                   // amplitude at each harmonic bin K0*h
    var out = [], h, n;
    for (h = 1; h <= H; h++){ var k = K0 * h, re = 0, im = 0; for (n = 0; n < N; n++){ var a = 2 * Math.PI * k * n / N; re += y[n] * Math.cos(a); im -= y[n] * Math.sin(a); } out.push(2 * Math.sqrt(re * re + im * im) / N); }
    return out;
  }
  function draw(){
    var drive = +driveEl.value;
    if (driveL) driveL.textContent = drive <= 0.05 ? 'clean' : drive < 3.5 ? 'gentle' : drive < 7 ? 'pushed' : 'slammed';
    if (info) info.textContent = mode === 'tube' ? 'asymmetric curve · even (2nd)' : 'symmetric clip · odd → square';
    var y = series(drive);
    if (xc){                                                                 // transfer curve: output vs input, identity ghosted
      var W = xd.w, H = xd.h; xc.clearRect(0, 0, W, H);
      xc.strokeStyle = '#efe6d8'; xc.lineWidth = 1; xc.beginPath(); xc.moveTo(0, H / 2); xc.lineTo(W, H / 2); xc.moveTo(W / 2, 0); xc.lineTo(W / 2, H); xc.stroke();
      xc.strokeStyle = '#d9cbb6'; xc.setLineDash([3, 3]); xc.beginPath(); xc.moveTo(6, H - 6); xc.lineTo(W - 6, 6); xc.stroke(); xc.setLineDash([]);
      var pk = 1e-9; for (var t = 0; t <= 140; t++){ var av = Math.abs(shape(t / 140 * 2 - 1, drive)); if (av > pk) pk = av; }   // scale the curve to fill the box (honest asymmetry, no false clamp)
      xc.strokeStyle = '#a8541f'; xc.lineWidth = 1.9; xc.beginPath();
      for (var i = 0; i <= 140; i++){ var xin = i / 140 * 2 - 1, yo = shape(xin, drive) / pk, px = 6 + (xin + 1) / 2 * (W - 12), py = (H - 6) - (yo + 1) / 2 * (H - 12); i ? xc.lineTo(px, py) : xc.moveTo(px, py); }
      xc.stroke();
    }
    if (wc){                                                                 // waveform: input sine (ghost) + driven output
      var W2 = wd.w, H2 = wd.h, mid = H2 / 2, amp = H2 * 0.40; wc.clearRect(0, 0, W2, H2);
      wc.strokeStyle = '#efe6d8'; wc.beginPath(); wc.moveTo(0, mid); wc.lineTo(W2, mid); wc.stroke();
      wc.strokeStyle = '#cbb89e'; wc.lineWidth = 1.2; wc.beginPath();
      for (var s = 0; s <= W2; s++){ var th = s / W2 * 4 * Math.PI, yy = mid - Math.sin(th) * amp * A; s ? wc.lineTo(s, yy) : wc.moveTo(s, yy); }
      wc.stroke();
      wc.strokeStyle = '#a8541f'; wc.lineWidth = 1.9; wc.beginPath();
      var span = (N / K0) * 2;                                               // 2 cycles of the driven wave
      for (var j = 0; j <= span; j++){ var xx = j / span * W2, yv = mid - y[j % N] * amp; j ? wc.lineTo(xx, yv) : wc.moveTo(xx, yv); }
      wc.stroke();
    }
    if (sc){                                                                 // harmonic bars, labeled by multiple of the note
      var W3 = sd.w, H3 = sd.h, HN = 12, mags = harmonics(y, HN), f0 = mags[0] || 1e-9;
      var base = H3 - 16, top = 10, slot = W3 / (HN + 1); sc.clearRect(0, 0, W3, H3);
      sc.strokeStyle = '#e0d3c2'; sc.lineWidth = 1; sc.beginPath(); sc.moveTo(0, base); sc.lineTo(W3, base); sc.stroke();
      sc.font = '7.5pt "Courier New",monospace'; sc.textAlign = 'center';
      for (var h = 1; h <= HN; h++){
        var rel = mags[h - 1] / f0; if (rel > 1) rel = 1;
        var bx = slot * h, bw = Math.min(16, slot * 0.5), bh = rel * (base - top), even = (h % 2) === 0;
        sc.fillStyle = h === 1 ? '#7a6141' : even ? '#a8541f' : '#d29a6a';   // fundamental neutral, even = accent, odd = light
        sc.fillRect(bx - bw / 2, base - bh, bw, Math.max(bh, 0.6));
        sc.fillStyle = h === 2 ? '#83400f' : '#a8977c';
        sc.fillText(h + '×', bx, H3 - 4);
      }
    }
  }
  var tVoice = DACAudio.wire(playBtn, function(ac){                           // live: a sine through the transfer curve, retuned as you move
    return DACAudio.shaperVoice(ac, 165, function(){ var d = +driveEl.value; return DACAudio.curve(function(x){ return shape(x, d); }); }, 0.2);
  });
  for (var b = 0; b < modeBtns.length; b++){
    modeBtns[b].addEventListener('click', function(){ var btn = this; mode = btn.getAttribute('data-mode'); for (var k = 0; k < modeBtns.length; k++) modeBtns[k].setAttribute('aria-pressed', modeBtns[k] === btn ? 'true' : 'false'); draw(); tVoice.retune(); });
  }
  driveEl.addEventListener('input', function(){ draw(); tVoice.retune(); });
  draw();
})();
